/* LeaveFlowMapper.selectDeductibleRemainingSum */
SELECT COALESCE(SUM(G.GRANT_DAYS - G.USED_DAYS), 0)
  FROM TB_USER_LEAVE_GRANT G
 WHERE G.CMPNY_CD = #{cmpnyCd}
   AND G.USER_CD  = #{userCd}
   AND G.LEAVE_CD = #{leaveCd}
   AND G.DEL_YN   = 'N'
   AND G.STATUS   = 'ACTIVE'
   AND G.AVAIL_FROM_DATE <= #{workYmd}
   AND G.AVAIL_TO_DATE   >= #{workYmd}
   AND (G.GRANT_DAYS - G.USED_DAYS) > 0

/* LeaveFlowMapper.selectGrantIdsByReqId */
SELECT DISTINCT U.GRANT_ID
  FROM TB_USER_LEAVE_USE U
 WHERE U.CMPNY_CD = #{cmpnyCd}
   AND U.REQ_ID   = #{reqId}
   AND U.GRANT_ID IS NOT NULL
   AND U.DEL_YN   = 'N'

/* LeaveFlowMapper.selectMyPendingLeaveApprovals */ SELECT AP.REQ_ID AS reqId , AP.APPROVAL_STEP AS approvalStep , R.USER_CD AS requesterUserCd , FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'USER_NM', R.USER_CD, null) AS requesterUserNm
, FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'NODE', R.SITE_CD, COALESCE(NULLIF(R.NODE_CD, ''), ( SELECT RU.NODE_CD FROM TB_USER RU WHERE RU.CMPNY_CD = R.CMPNY_CD AND RU.SITE_CD = R.SITE_CD AND RU.USER_CD = R.USER_CD LIMIT 1 ))) AS nodeNm , R.WORK_YMD AS workYmd , R.LEAVE_TYPE AS leaveType , U.LEAVE_CD AS leaveCd , LT.LEAVE_NO AS leaveNo , LT.LEAVE_NM AS leaveNm , U.USE_UNIT_TYPE AS useUnitType , FNC_CMM_INFO_SRCH(R.CMPNY_CD, 'SYST_VAL', U.USE_UNIT_TYPE, 'SYS025') AS unitNm , R.LEAVE_DAYS AS leaveDays , U.LEAVE_MINUTES AS leaveMinutes , R.START_TIME AS startTime , R.END_TIME AS endTime , R.REQ_REASON AS reqReason , DATE_FORMAT(R.INSERT_DATE, '%Y-%m-%dT%H:%i:%s') AS reqDate , CASE WHEN R.USER_CD = #{approverUserCd} THEN 'Y' ELSE 'N' END AS selfYn FROM TB_USER_ATTD_REQ_APPROVAL AP JOIN TB_USER_ATTD_REQ R ON R.CMPNY_CD = AP.CMPNY_CD AND R.REQ_ID = AP.REQ_ID
LEFT JOIN TB_USER_LEAVE_USE U ON U.CMPNY_CD = R.CMPNY_CD AND U.DEL_YN = 'N' AND ( (R.REQ_TYPE = '05' AND U.REQ_ID = R.REQ_ID AND U.LEAVE_STATUS = 'CONFIRMED' AND U.LEAVE_ID = ( SELECT MIN(X.LEAVE_ID) FROM TB_USER_LEAVE_USE X WHERE X.CMPNY_CD = R.CMPNY_CD AND X.REQ_ID = R.REQ_ID AND X.LEAVE_STATUS = 'CONFIRMED' AND X.DEL_YN = 'N' )) OR (R.REQ_TYPE = '06' AND U.LEAVE_ID = R.TARGET_ID) ) LEFT JOIN TB_LEAVE_TYPE_MGMT LT ON LT.CMPNY_CD = U.CMPNY_CD AND LT.LEAVE_CD = U.LEAVE_CD WHERE AP.CMPNY_CD = #{cmpnyCd} AND AP.APPROVER_USER_CD = #{approverUserCd} AND AP.APPROVAL_STATUS = '01' AND R.REQ_TYPE IN ('05', '06') AND R.REQ_STATUS = '01' AND R.DEL_YN = 'N' ORDER BY R.INSERT_DATE DESC

/* LeaveFlowMapper.countReqSplitRows */
SELECT COUNT(*)
  FROM TB_USER_LEAVE_USE U
 WHERE U.CMPNY_CD     = #{cmpnyCd}
   AND U.LEAVE_STATUS = 'CONFIRMED'
   AND U.DEL_YN       = 'N'
   AND U.REQ_ID       = (
       SELECT B.REQ_ID
         FROM TB_USER_LEAVE_USE B
        WHERE B.CMPNY_CD = #{cmpnyCd}
          AND B.LEAVE_ID = #{leaveId}
          AND B.DEL_YN   = 'N'
        LIMIT 1
   )

